    // Check if the input is valid
    if (terminators == null || terminators.length == 0) {
        throw new IllegalArgumentException("Invalid terminators");
    }

    // Initialize the token and the current character
    String token = "";
    char currentChar = ' ';

    // Loop through the input string
    for (int i = 0; i < input.length(); i++) {
        currentChar = input.charAt(i);

        // Check if the current character is a terminator
        for (char terminator : terminators) {
            if (currentChar == terminator) {
                // If it is, return the token
                return token;
            }
        }

        // If the current character is not a terminator, add it to the token
        token += currentChar;
    }

    // If the loop completes and no terminator is found, return the token
    return token;
}

