public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Check if the target graph is null
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }

    // Check if the result map is null
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    // Get the number of vertices in the target graph
    int numVertices = target.getNumVertices();

    // Check if the number of vertices is even
    if (numVertices % 2 != 0) {
        throw new IllegalArgumentException("Number of vertices must be even");
    }

    // Get the number of edges in the target graph
    int numEdges = target.getNumEdges();

    // Check if the number of edges is even
    if (numEdges % 2 != 0) {
        throw new IllegalArgumentException("Number of edges must be even");
    }

    // Create a new graph with the same number of vertices and edges as the target graph
    Graph<V, E> newGraph = new Graph<V, E>(numVertices, numEdges);

    // Add the vertices from the target graph to the new graph
    for (V vertex : target.getVertices()) {
        newGraph.addVertex(vertex);
    }

    // Add the edges from the target graph to the new graph
    for (E edge : target.getEdges()) {
        newGraph.addEdge(edge);
    }

    // Add the vertices from the result map to the new graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        newGraph.addVertex(entry.getValue());
    }

    // Add the edges from the result map to the new graph
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        newGraph.addEdge(entry.getKey(), entry.getValue());
    }

    // Return the new graph
    return newGraph;
}

