    // Check if the relative path is absolute
    if (relativePathComponents[0].equals("")) {
        // If the relative path is absolute, return the full path
        return path;
    }

    // Check if the relative path is relative to the current directory
    if (relativePathComponents[0].equals(".")) {
        // If the relative path is relative to the current directory, return the full path
        return path;
    }

    // Check if the relative path is relative to the parent directory
    if (relativePathComponents[0].equals("..")) {
        // If the relative path is relative to the parent directory, return the full path
        return path.substring(0, path.lastIndexOf("/") + 1) + relativePath;
    }

    // If the relative path is not absolute, relative to the current directory, or relative to the parent directory,
    // return the full path
    return path + "/" + relativePath;
}

