public ByteVector putInt(final int intValue) {
    if (intValue < 0) {
        throw new IllegalArgumentException("intValue must be non-negative");
    }
    int numBytes = (int) Math.ceil(Math.log(intValue + 1) / Math.log(256));
    if (numBytes > 4) {
        throw new IllegalArgumentException("intValue is too large to be represented as an int");
    }
    byte[] bytes = new byte[numBytes];
    for (int i = 0; i < numBytes; i++) {
        bytes[i] = (byte) ((intValue >> (8 * i)) & 0xFF);
    }
    return this.put(bytes);
}

